mapper.insert:

INSERT INTO unidad_educativa (uned_rbd, ensenanza, grado, letra, jornada, cupo, educador_rut, educador_dv)
VALUES (#{rbd}, #{ensenanza}, #{grado}, #{letra}, #{jornada}, #{cupo}, #{educador.rut}, #{educador.dv});


INSERT INTO grupo (grup_letra, grup_cupo)
VALUES (#{letra}, #{cupo});


INSERT INTO grado (grad_nombre)
VALUES (#{grado});


INSERT INTO sostenedor (sost_rut, sost_dv)
VALUES (#{sostenedor.rut}, #{sostenedor.dv});


INSERT INTO jornada (jorn_nombre)
VALUES (#{jornada});

mapper.update:
UPDATE unidad_educativa
SET ensenanza = #{ensenanza},
grado = #{grado},
letra = #{letra},
jornada = #{jornada},
cupo = #{cupo},
educador_rut = #{educador.rut},
educador_dv = #{educador.dv}
WHERE uned_rbd = #{rbd};


UPDATE sostenedor
SET sost_rut = #{sostenedor.rut}, sost_dv = #{sostenedor.dv}
WHERE uned_rbd = #{rbd};


UPDATE jornada
SET jorn_nombre = #{jornada}
WHERE uned_rbd = #{rbd};

mapper.delete:
DELETE FROM unidad_educativa WHERE uned_rbd = #{rbd};


DELETE FROM grupo WHERE uned_rbd = #{rbd};
DELETE FROM grado WHERE uned_rbd = #{rbd};
DELETE FROM sostenedor WHERE uned_rbd = #{rbd};
DELETE FROM jornada WHERE uned_rbd = #{rbd};
